        { "type": "MetricCard", "label": "Total spend (7d)", "formatAs": "currency",
          "dataSource": {"kind":"llm_calls_sql","sql":"SELECT SUM(cost_usd) FROM llm_calls WHERE timestamp_ms > epoch_ms(CAST(now() AS TIMESTAMP) - INTERVAL 7 DAYS)"} },
        { "type": "MetricCard", "label": "Calls (24h)",
          "dataSource": {"kind":"llm_calls_sql","sql":"SELECT COUNT(*) FROM llm_calls WHERE timestamp_ms > epoch_ms(CAST(now() AS TIMESTAMP) - INTERVAL 1 DAY)"} }
      ] },
      { "type": "BarChart", "xField": "agent_id", "yField": "spend",
        "dataSource": {"kind":"llm_calls_sql","sql":"SELECT agent_id, SUM(cost_usd) AS spend FROM llm_calls GROUP BY agent_id ORDER BY spend DESC LIMIT 10"} }
    ]
  }
}

